create schema if not exists schooly_private;
grant usage on schema schooly_private to authenticated;

create or replace function schooly_private.is_school_member(target_school_id uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.school_memberships where school_id = target_school_id and user_id = auth.uid());
$$;

create or replace function schooly_private.is_approved_school_member(target_school_id uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.school_memberships membership
    join public.schools school on school.id = membership.school_id
    where membership.school_id = target_school_id
      and membership.user_id = auth.uid()
      and school.approval_status = 'approved'
  );
$$;

create or replace function schooly_private.is_platform_admin() returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.platform_admins where user_id = auth.uid() and status = 'active');
$$;

grant execute on function schooly_private.is_school_member(uuid) to authenticated;
grant execute on function schooly_private.is_approved_school_member(uuid) to authenticated;
grant execute on function schooly_private.is_platform_admin() to authenticated;

alter policy schools_select_member on public.schools using (schooly_private.is_school_member(id));
alter policy memberships_select_member on public.school_memberships using (schooly_private.is_school_member(school_id));
alter policy platform_admins_select_self_or_admin on public.platform_admins using (user_id = auth.uid() or schooly_private.is_platform_admin());
