create or replace function public.approve_school(p_school_id uuid, p_decision text, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public, schooly_private as $$
declare
  updated_school public.schools;
begin
  if not schooly_private.is_platform_admin() then raise exception 'Platform administrator required'; end if;
  if p_decision not in ('approved','rejected','suspended') then raise exception 'Unsupported school decision'; end if;
  update public.schools set approval_status = p_decision, approved_at = case when p_decision = 'approved' then now() else null end, approved_by = case when p_decision = 'approved' then auth.uid() else null end, rejection_reason = case when p_decision = 'rejected' then nullif(trim(p_reason), '') else null end where id = p_school_id returning * into updated_school;
  if updated_school.id is null then raise exception 'School not found'; end if;
  return jsonb_build_object('id', updated_school.id, 'status', updated_school.approval_status, 'name', updated_school.name);
end;
$$;

revoke all on function public.is_school_member(uuid) from public, anon, authenticated;
revoke all on function public.is_approved_school_member(uuid) from public, anon, authenticated;
revoke all on function public.is_platform_admin() from public, anon, authenticated;
drop function public.is_school_member(uuid);
drop function public.is_approved_school_member(uuid);
drop function public.is_platform_admin();
